result = await mcp.call_tool("tools", "ox-bridge-write", {"path": "/workspace/src/steering.ts", "content": "/**
 * Seek vs Pursuit steering behaviors — deterministic fixed-step simulation.
 *
 * Target: moves in a straight line at TARGET_SPEED.
 * Agent : max speed AGENT_SPEED, instant steering (velocity snaps to the
 *         desired direction * speed each tick), integrated with fixed DT.
 *
 * - seek   : aim at the target's *current* position.
 * - pursuit: aim at the target's position extrapolated by
 *            distance / agentSpeed (classic Reynolds-style prediction).
 */

export interface Vec {
  x: number;
  y: number;
}

export const AGENT_SPEED = 5;
export const TARGET_SPEED = 3;
export const DT = 0.05; // seconds per tick (fixed step => deterministic)
export const INTERCEPT_RADIUS = 1;
export const MAX_TICKS = 20_000;

export const add = (a: Vec, b: Vec): Vec => ({ x: a.x + b.x, y: a.y + b.y });
export const sub = (a: Vec, b: Vec): Vec => ({ x: a.x - b.x, y: a.y - b.y });
export const scale = (a: Vec, s: number): Vec => ({ x: a.x * s, y: a.y * s });
export const len = (a: Vec): number => Math.hypot(a.x, a.y);

export function norm(a: Vec): Vec {
  const l = len(a);
  if (l === 0) return { x: 0, y: 0 };
  return { x: a.x / l, y: a.y / l };
}

export interface Geometry {
  name: string;
  agentStart: Vec;
  targetStart: Vec;
  /** Unit direction of the target's straight-line motion. */
  targetDir: Vec;
}

export type Behavior = "seek" | "pursuit";

/** Advance agent one fixed step toward `aimPoint` at full speed. */
function steerStep(agentPos: Vec, aimPoint: Vec): Vec {
  const desired = scale(norm(sub(aimPoint, agentPos)), AGENT_SPEED);
  return add(agentPos, scale(desired, DT));
}

function targetAt(geo: Geometry, ticks: number): Vec {
  return add(geo.targetStart, scale(geo.targetDir, TARGET_SPEED * ticks * DT));
}

/**
 * Simulate until the agent is within INTERCEPT_RADIUS of the target.
 * Returns the tick count of first interception, or Infinity.
 */
export function simulate(geo: Geometry, behavior: Behavior): number {
  let agentPos = geo.agentStart;
  for (let tick = 1; tick <= MAX_TICKS; tick++) {
    const targetPos = targetAt(geo, tick); // exact analytic straight-line motion

    let aim: Vec;
    if (behavior === "seek") {
      aim = targetPos;
    } else {
      // pursuit: extrapolate target forward by distance / agentSpeed
      const t = len(sub(targetPos, agentPos)) / AGENT_SPEED;
      aim = add(targetPos, scale(geo.targetDir, TARGET_SPEED * t));
    }

    agentPos = steerStep(agentPos, aim);
    if (len(sub(agentPos, targetPos)) <= INTERCEPT_RADIUS) return tick;
  }
  return Infinity;
}

/** Full trajectory of the agent (deterministic), for debugging/inspection. */
export function trajectory(geo: Geometry, behavior: Behavior, ticks: number): Vec[] {
  const pts: Vec[] = [geo.agentStart];
  let agentPos = geo.agentStart;
  for (let tick = 1; tick <= ticks; tick++) {
    const targetPos = targetAt(geo, tick);
    let aim: Vec;
    if (behavior === "seek") {
      aim = targetPos;
    } else {
      const t = len(sub(targetPos, agentPos)) / AGENT_SPEED;
      aim = add(targetPos, scale(geo.targetDir, TARGET_SPEED * t));
    }
    agentPos = steerStep(agentPos, aim);
    pts.push(agentPos);
  }
  return pts;
}
"})
