result = await mcp.call_tool("tools", "ox-bridge-write", {"path": "/workspace/tests/interception.test.ts", "content": "import { describe, expect, it } from "vitest";
import {
  AGENT_SPEED,
  TARGET_SPEED,
  INTERCEPT_RADIUS,
  Geometry,
  simulate,
  trajectory,
} from "../src/steering.js";

/**
 * Three geometries. Target always moves in a straight line at speed 3;
 * agent max speed is 5 in every case.
 */
const geometries: Geometry[] = [
  {
    // Crossing: target cuts across the agent's front, left -> right.
    name: "crossing",
    agentStart: { x: 0, y: 0 },
    targetStart: { x: 40, y: -30 },
    targetDir: { x: 0, y: 1 },
  },
  {
    // Trailing: target flees directly away from the agent.
    name: "trailing",
    agentStart: { x: 0, y: 0 },
    targetStart: { x: 20, y: 0 },
    targetDir: { x: 1, y: 0 },
  },
  {
    // Head-on offset: target approaches with lateral offset.
    name: "head-on-offset",
    agentStart: { x: 0, y: 0 },
    targetStart: { x: 60, y: 12 },
    targetDir: { x: -1, y: 0 },
  },
];

describe("seek vs pursuit interception", () => {
  it.each(geometries)(
    "$name: both intercept; pursuit strictly earlier than seek",
    (geo) => {
      const seekTicks = simulate(geo, "seek");
      const pursuitTicks = simulate(geo, "pursuit");

      console.log(
        `[${geo.name}] seek intercepted at tick ${seekTicks}, ` +
          `pursuit at tick ${pursuitTicks}`
      );

      expect(seekTicks).toBeLessThan(Infinity);
      expect(pursuitTicks).toBeLessThan(Infinity);
      expect(pursuitTicks).toBeLessThan(seekTicks);

      // Sanity: trajectories are deterministic — re-running yields identical paths.
      const t1 = trajectory(geo, "pursuit", pursuitTicks);
      const t2 = trajectory(geo, "pursuit", pursuitTicks);
      expect(t1).toEqual(t2);
      expect(
        Math.hypot(t1[t1.length - 1].x, t1[t1.length - 1].y)
      ).toBeGreaterThanOrEqual(0);
    }
  );

  it("uses the specified speeds", () => {
    expect(AGENT_SPEED).toBe(5);
    expect(TARGET_SPEED).toBe(3);
    expect(INTERCEPT_RADIUS).toBe(1);
  });
});
"})
